<?php
if(!isset($db)){http_response_code(404);exit;}
function departureSetup(){
q("CREATE TABLE IF NOT EXISTS onb_departures(id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,capacity INT NOT NULL,adult DECIMAL(12,2) NOT NULL,child DECIMAL(12,2) NOT NULL,group_min INT NOT NULL,group_price DECIMAL(12,2) NOT NULL,early_until DATE NULL,early_price DECIMAL(12,2) NOT NULL,active TINYINT NOT NULL,terms TEXT NOT NULL,supplier_notes TEXT NOT NULL) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_departure_requests(id INT AUTO_INCREMENT PRIMARY KEY,departure_id INT NOT NULL,user_id INT NOT NULL,adults INT NOT NULL,children INT NOT NULL,total DECIMAL(12,2) NOT NULL,discount_code VARCHAR(100) NOT NULL,activities TEXT NOT NULL,terms TEXT NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_departure_options(id INT AUTO_INCREMENT PRIMARY KEY,departure_id INT NOT NULL,label VARCHAR(150) NOT NULL,price DECIMAL(12,2) NOT NULL) ENGINE=InnoDB");
}
function depCheckoutSetup(){q("CREATE TABLE IF NOT EXISTS onb_checkout(request_id INT PRIMARY KEY,booking_id INT UNIQUE NULL,traveller_name VARCHAR(120) NOT NULL,phone VARCHAR(60) NOT NULL,flexible TINYINT NOT NULL,insurance TINYINT NOT NULL,accepted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");}
function depCheckoutConvert($u,$admin){global $db;if(!$u||$admin)throw new RuntimeException('Traveller sign-in required.');departureSetup();depCheckoutSetup();bookingSetup();bookingPolicySetup();$db->beginTransaction();try{$r=q("SELECT * FROM onb_departure_requests WHERE id=? AND user_id=? FOR UPDATE",[(int)p('id'),$u['id']])->fetch();if(!$r||$r['status']!=='reserved'||(int)$r['adults']!==1||(int)$r['children']!==0)throw new RuntimeException('Only approved single-traveller reservations can be checked out online.');$d=q('SELECT * FROM onb_departures WHERE id=? FOR UPDATE',[$r['departure_id']])->fetch();$x=q('SELECT * FROM onb_checkout WHERE request_id=? FOR UPDATE',[$r['id']])->fetch();if(!$x||$x['booking_id']||!$d||!$d['active']||$d['start_date']<date('Y-m-d'))throw new RuntimeException('Checkout unavailable or already completed.');$ref='ONB-'.strtoupper(bin2hex(random_bytes(6)));q("INSERT INTO onb_bookings(ref,trip_id,user_id,stage,price) VALUES(?,?,?,'accepted',?)",[$ref,$d['trip_id'],$u['id'],$r['total']]);$bid=(int)$db->lastInsertId();q('INSERT INTO onb_booking_policy(booking_id,departure,flexible,insurance) VALUES(?,?,?,?)',[$bid,$d['start_date'],$x['flexible'],$x['insurance']]);q('UPDATE onb_checkout SET booking_id=? WHERE request_id=?',[$bid,$r['id']]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=bookings');}
function depNumber($k,$max=1000000){$v=p($k);if(!preg_match('/^\d+(\.\d{1,2})?$/D',$v)||(float)$v>$max)throw new RuntimeException('Invalid amount: '.$k);return (float)$v;}
function depInt($k,$max=1000){$v=depNumber($k,$max);if(floor($v)!==$v)throw new RuntimeException('Whole numbers required.');return (int)$v;}
function depDate($k){$v=p($k);$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new RuntimeException('Invalid date.');return $v;}
function depUsed($id){return (int)q("SELECT COALESCE(SUM(adults+children),0) FROM onb_departure_requests WHERE departure_id=? AND status='reserved'",[$id])->fetchColumn();}
function departureAction($action,$u,$admin){global $db;departureSetup();depCheckoutSetup();if($action==='dep_checkout')depCheckoutConvert($u,$admin);
if($action==='dep_create'&&$admin){
$trip=depInt('trip_id',2147483647);if(!q('SELECT id FROM trips WHERE id=?',[$trip])->fetchColumn())throw new RuntimeException('Invalid journey.');
$start=depDate('start');$end=depDate('end');$cap=depInt('capacity');$adult=depNumber('adult');$child=depNumber('child');$min=depInt('group_min');$group=depNumber('group_price');$early=p('early_until')?depDate('early_until'):null;$earlyPrice=depNumber('early_price');
if($end<$start||!$cap||!$adult||!p('terms')||($min&&(!$group||$min>$cap))||($early&&(!$earlyPrice||$early>$start)))throw new RuntimeException('Check dates, prices, capacity and terms.');
q('INSERT INTO onb_departures(trip_id,start_date,end_date,capacity,adult,child,group_min,group_price,early_until,early_price,active,terms,supplier_notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$trip,$start,$end,$cap,$adult,$child,$min,$group,$early,$earlyPrice,1,p('terms'),p('supplier_notes')]);go('page=departures');
}
if($action==='dep_option'&&$admin){$id=depInt('id',2147483647);if(!q('SELECT id FROM onb_departures WHERE id=?',[$id])->fetchColumn()||!p('label')||strlen(p('label'))>150)throw new RuntimeException('Invalid activity.');q('INSERT INTO onb_departure_options(departure_id,label,price) VALUES(?,?,?)',[$id,p('label'),depNumber('price')]);go('page=departures');}
if($action==='dep_status'&&$admin){$db->beginTransaction();try{$id=depInt('id',2147483647);$r=q('SELECT * FROM onb_departure_requests WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r)throw new RuntimeException('Request unavailable.');$d=q('SELECT * FROM onb_departures WHERE id=? FOR UPDATE',[$r['departure_id']])->fetch();$next=p('status');if(q('SELECT booking_id FROM onb_checkout WHERE request_id=? AND booking_id IS NOT NULL',[$id])->fetchColumn()&&$next!==$r['status'])throw new RuntimeException('Manage linked bookings in Bookings & Finance.');if(!in_array($next,['reserved','declined','waitlist'],true))throw new RuntimeException('Invalid status.');if($next==='reserved'&&$r['status']!=='reserved'&&(!$d['active']||depUsed($d['id'])+$r['adults']+$r['children']>$d['capacity']))throw new RuntimeException('Insufficient seats.');q('UPDATE onb_departure_requests SET status=? WHERE id=?',[$next,$id]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=departures');}
if($action==='dep_request'&&$u&&!$admin){growthSetup();$db->beginTransaction();try{$id=depInt('id',2147483647);$d=q('SELECT d.* FROM onb_departures d JOIN trips t ON t.id=d.trip_id WHERE d.id=? AND d.active=1 AND t.published=1 AND d.start_date>=CURRENT_DATE FOR UPDATE',[$id])->fetch();if(!$d||p('accept')!=='yes')throw new RuntimeException('Select a departure and acknowledge its terms.');if(q("SELECT id FROM onb_departure_requests WHERE departure_id=? AND user_id=? AND status IN ('requested','reserved','waitlist')",[$id,$u['id']])->fetchColumn())throw new RuntimeException('You already have an active request for this departure.');$a=depInt('adults',50);$k=depInt('children',50);if(!$a||$a+$k>$d['capacity'])throw new RuntimeException('Invalid group size.');$rate=(float)$d['adult'];if($d['group_min']&&$a+$k>=$d['group_min'])$rate=min($rate,(float)$d['group_price']);if($d['early_until']&&$d['early_until']>=(new DateTimeImmutable('now',new DateTimeZone('America/Vancouver')))->format('Y-m-d'))$rate=min($rate,(float)$d['early_price']);$total=$a*$rate+$k*(float)$d['child'];$options=[];foreach(q('SELECT * FROM onb_departure_options WHERE departure_id=?',[$id]) as $o){if(isset($_POST['opt_'.$o['id']])){$total+=(float)$o['price']*($a+$k);$options[]=$o['label'].' (CAD '.$o['price'].' per traveller)';}}
$code=strtoupper(p('discount'));if($code!==''){$r=q('SELECT percent FROM onb_discounts WHERE code=? AND active=1',[$code])->fetchColumn();if(!$r)throw new RuntimeException('Invalid discount.');$f=q('SELECT amount FROM onb_discount_fixed WHERE code=?',[$code])->fetchColumn();$total-=$f!==false?(float)$f:round($total*$r/100,2);}if($total<=0)throw new RuntimeException('Invalid total.');
$flex=p('flexible')==='1';$insurance=p('insurance')==='1';$name=p('traveller_name');$phone=p('phone');if(!$name||strlen($name)>120||!$phone||strlen($phone)>60)throw new RuntimeException('Traveller name and phone required.');if($flex&&$a+$k!==1)throw new RuntimeException('Flexible group quotes require our team.');if($flex)$total+=200;$status=depUsed($id)+$a+$k>$d['capacity']?'waitlist':'requested';q('INSERT INTO onb_departure_requests(departure_id,user_id,adults,children,total,discount_code,activities,terms,status) VALUES(?,?,?,?,?,?,?,?,?)',[$id,$u['id'],$a,$k,round($total,2),$code,implode("\n",$options),$d['terms']."\nBooking type: ".($flex?'Flexible (+ CAD 200)':'Standard'),$status]);$requestId=(int)$db->lastInsertId();q('INSERT INTO onb_checkout(request_id,traveller_name,phone,flexible,insurance) VALUES(?,?,?,?,?)',[$requestId,$name,$phone,$flex?1:0,$insurance?1:0]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=departures');}
throw new RuntimeException('Access denied.');
}
function departureView($u,$admin){departureSetup();depCheckoutSetup();echo '<div class="onb-dash"><div class="dash-hero"><h1>Departures & reservations</h1><p>Choose your journey and request a quotation.</p></div>';
if($admin){form('dep_create');echo '<label>Journey<select name="trip_id">';foreach(q('SELECT id,title FROM trips') as $t)echo '<option value="'.h($t['id']).'">'.h($t['title']).'</option>';echo '</select></label>';foreach(['start'=>'Departure','end'=>'Return'] as $k=>$v)field($k,$v,'','date');foreach(['capacity'=>'Capacity','adult'=>'Adult CAD','child'=>'Child CAD','group_min'=>'Group threshold (0 disables)','group_price'=>'Group adult CAD','early_price'=>'Early bird adult CAD'] as $k=>$v)field($k,$v,'0');echo '<label>Early bird deadline<input type="date" name="early_until"></label>';area('terms','Departure-specific booking and cancellation terms');area('supplier_notes','Private flight, hotel and supplier reservation notes');echo '<button>Create departure</button></form>';}
foreach(q('SELECT d.*,t.title FROM onb_departures d JOIN trips t ON t.id=d.trip_id '.($admin?'':'WHERE d.active=1 AND t.published=1 AND d.start_date>=CURRENT_DATE').' ORDER BY d.start_date') as $d){echo '<article><h2>'.h($d['title']).'</h2><p>'.h($d['start_date'].' — '.$d['end_date']).' · '.max(0,$d['capacity']-depUsed($d['id'])).' seats available</p><p>Adult CAD '.h($d['adult']).' · Child CAD '.h($d['child']).'</p>';if($d['group_min'])echo '<p>Group adult price CAD '.h($d['group_price']).' from '.h($d['group_min']).' travellers.</p>';if($d['early_until'])echo '<p>Early bird CAD '.h($d['early_price']).' until '.h($d['early_until']).'</p>';
if($admin){echo '<pre>'.h($d['supplier_notes']).'</pre>';form('dep_option');echo '<input type="hidden" name="id" value="'.h($d['id']).'">';field('label','Optional activity');field('price','CAD per traveller');echo '<button>Add activity</button></form>';}
elseif($u){form('dep_request');echo '<input type="hidden" name="id" value="'.h($d['id']).'">';field('traveller_name','Traveller full name',$u['name']);field('phone','Contact phone');echo '<label><input type="checkbox" name="flexible" value="1"> Flexible booking (+ CAD 200, single traveller only)</label><label><input type="checkbox" name="insurance" value="1"> Request travel insurance information</label>';field('adults','Adults','1','number');field('children','Children','0','number');foreach(q('SELECT * FROM onb_departure_options WHERE departure_id=?',[$d['id']]) as $o)echo '<label><input type="checkbox" name="opt_'.h($o['id']).'"> '.h($o['label'].' — CAD '.$o['price'].' per person').'</label>';echo '<label>Discount code<input name="discount"></label><pre>'.h($d['terms']).'</pre><label><input type="checkbox" name="accept" value="yes" required> I acknowledge these terms for my quotation request.</label><button>Request quotation</button></form><p>No payment or confirmed booking at this stage.</p>';}else echo '<a href="?page=login">Sign in to request a quotation</a>';echo '</article>';}
if($u){echo '<h2>Quotation requests</h2>';foreach(q('SELECT r.*,t.title,u.email FROM onb_departure_requests r JOIN onb_departures d ON d.id=r.departure_id JOIN trips t ON t.id=d.trip_id JOIN users u ON u.id=r.user_id'.($admin?'':' WHERE r.user_id=?').' ORDER BY r.id DESC',$admin?[]:[$u['id']]) as $r){echo '<article><h3>'.h($r['title'].' — '.$r['status']).'</h3><p>'.h($r['email']).' · '.h($r['adults']+$r['children']).' travellers · CAD '.h($r['total']).'</p><pre>'.h($r['activities']).'</pre>';if($admin){form('dep_status');echo '<input type="hidden" name="id" value="'.h($r['id']).'"><select name="status"><option>reserved</option><option>waitlist</option><option>declined</option></select><button>Update reservation</button></form>';}else{$x=q('SELECT * FROM onb_checkout WHERE request_id=?',[$r['id']])->fetch();if($x&&$x['booking_id'])echo '<a href="?page=bookings">View booking</a>';elseif($x&&$r['status']==='reserved'&&(int)$r['adults']===1&&(int)$r['children']===0){form('dep_checkout');echo '<input type="hidden" name="id" value="'.h($r['id']).'"><button>Complete checkout</button></form>';}}echo '</article>';}}echo '</div>';}
